const customer = await afriex.customers.create({
  fullName: "John Doe",
  email: "john@example.com",
  phone: "+1234567890",
  countryCode: "US",
});

const response = await afriex.customers.list({
  page: 0,
  limit: 20,
  email: "john@example.com",
});

console.log(response.data);  // Customer[]
console.log(response.total); // Total count

const customer = await afriex.customers.update("customer-id", {
  fullName: "Jane Doe",
});

const customer = await afriex.customers.updateKyc("customer-id", {
  kyc: {
    documentType: "passport",
    documentNumber: "AB123456",
  },
});

const customer = await afriex.customers.verify("customer-id", {
  docType: "BVN",
  docValue: "22222222222",
});

const transaction = await afriex.transactions.create({
  customerId: "customer-id",
  sourceAmount: "10",
  destinationAmount: "5000",
  sourceCurrency: "USD",
  destinationCurrency: "NGN",
  destinationId: "payment-method-id",
  meta: {
    idempotencyKey: "unique-key-123",
    reference: "order-456",
    narration: "Payment for services",
  },
});

const response = await afriex.transactions.list({
  page: 0,
  limit: 20,
  status: ["PENDING", "PROCESSING"],
  currency: ["USD", "NGN"],
  fromDate: "2026-01-01T00:00:00.000Z",
  toDate: "2026-01-31T23:59:59.999Z",
});

console.log(response.data); // Transaction[]

const transaction = await afriex.transactions.authorize("transaction-id", {
  type: "OTP",
  otp: "123456",
});

const paymentMethod = await afriex.paymentMethods.create({
  channel: "BANK_ACCOUNT",
  customerId: "customer-id",
  accountName: "John Doe",
  accountNumber: "1234567890",
  countryCode: "NG",
  institution: {
    institutionCode: "044",
    institutionName: "Access Bank",
  },
});

const response = await afriex.paymentMethods.list({
  page: 1,
  limit: 20,
});

const institutions = await afriex.paymentMethods.getInstitutions({
  channel: "BANK_ACCOUNT",
  countryCode: "NG",
});

// Returns: Institution[], { institutionId, institutionName, institutionCode }

const accountInfo = await afriex.paymentMethods.resolveAccount({
  channel: "BANK_ACCOUNT",
  accountNumber: "1234567890",
  institutionCode: "044",
  countryCode: "NG",
});

// Returns: { recipientName, recipientEmail, recipientPhone }

const balances = await afriex.balance.getBalance({
  currencies: ["USD", "NGN", "GBP"],
});

// Returns: { USD: 10000, NGN: 5000000, GBP: 8000 }

const transaction = await afriex.balance.topUpSandbox({
  amount: 500,
  currency: "USD",
});

console.log(transaction.transactionId);
console.log(transaction.status); // 'SUCCESS'

const response = await afriex.rates.getRates({
  fromSymbols: "USD,NGN",
  toSymbols: "NGN,USD,GBP,KES",
});

console.log(response.rates);
console.log(response.updatedAt); // Unix timestamp

const response = await afriex.paymentMethods.getCryptoWallet({
  asset: "USDT", // or 'USDC'
  customerId: "optional-customer-id",
});

// Returns: { data: [{ address, network }], total, page }

const response = await afriex.paymentMethods.listVirtualAccounts({
  customerId: "customer-id",
  currency: "USD",
});

const account = await afriex.paymentMethods.createVirtualAccount({
  currency: "USD",
  label: "SALES",
  customerId: "optional-customer-id",
});

const poolAccount = await afriex.paymentMethods.listPoolAccounts({
  customerId: "customer-id",
  country: "NG",
});

const session = await afriex.checkout.createSession({
  amount: 500000,
  currency: "NGN",
  merchantReference: "order-2026-05-12-001",
  redirectUrl: "https://yourapp.com/checkout/return",
  customer: {
    name: "John Doe",
    email: "john@example.com",
    phone: "+2348192837465",
    countryCode: "NG",
  },
  // Send the same list everywhere; unsupported ones are dropped
  channels: ["VIRTUAL_BANK_ACCOUNT", "MOBILE_MONEY", "CARD"],
  metadata: { orderId: "order-456", cartId: "cart-123" },
});

// Redirect customer to session.checkoutUrl
console.log(session.checkoutUrl);
// What the payer will be shown, e.g. ["VIRTUAL_BANK_ACCOUNT", "CARD"]
console.log(session.channels);

const result = await afriex.webhooks.triggerTestWebhook({
  event: "TRANSACTION.UPDATED",
  resourceId: "transaction-id",
});

console.log(result); // { success: true, message: "..." }
